import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for Axis.equals(Object)
 */
public class Axis_equals_TriageGen0Test {

    private Axis axis1;
    private Axis axis2;

    // Since Axis is abstract, we need a concrete implementation for testing
    private static class TestAxis extends Axis {
        protected TestAxis(String label) {
            super(label);
        }

        @Override
        public void configure() {}

        @Override
        public AxisSpace reserveSpace(java.awt.Graphics2D g2, Plot plot, java.awt.geom.Rectangle2D plotArea, RectangleEdge edge, AxisSpace space) {
            return null;
        }

        @Override
        public AxisState draw(java.awt.Graphics2D g2, double cursor, java.awt.geom.Rectangle2D plotArea, java.awt.geom.Rectangle2D dataArea, RectangleEdge edge, PlotRenderingInfo plotState) {
            return null;
        }

        @Override
        public java.util.List<Number> refreshTicks(java.awt.Graphics2D g2, AxisState state, java.awt.geom.Rectangle2D dataArea, RectangleEdge edge) {
            return null;
        }
    }

    @Before
    public void setUp() {
        axis1 = new TestAxis("Label");
        axis2 = new TestAxis("Label");
    }

    @Test
    public void testEquals_Identity() {
        assertTrue(axis1.equals(axis1));
    }

    @Test
    public void testEquals_Null() {
        assertFalse(axis1.equals(null));
    }

    @Test
    public void testEquals_DifferentClass() {
        assertFalse(axis1.equals("Not an Axis"));
    }

    @Test
    public void testEquals_AllFieldsMatch() {
        // Set all fields to non-default values to ensure comparison logic is hit
        setupAxis(axis1);
        setupAxis(axis2);
        assertTrue(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchVisible() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setVisible(false);
        assertFalse(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchLabel() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setLabel("Different");
        assertFalse(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchLabelFont() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setLabelFont(new Font("Serif", Font.PLAIN, 12));
        assertFalse(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchLabelPaint() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setLabelPaint(Color.RED);
        assertFalse(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchLabelInsets() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setLabelInsets(new org.jfree.chart.util.RectangleInsets(1, 2, 3, 4));
        assertFalse(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchLabelAngle() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setLabelAngle(Math.PI);
        assertFalse(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchLabelToolTip() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setLabelToolTip("Tip A");
        axis2.setLabelToolTip("Tip B"); // ensure non-null
        axis1.setLabelToolTip("Tip A");
        axis2.setLabelToolTip("Tip B");
        assertFalse(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchLabelURL() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setLabelURL("http://a.com");
        axis2.setLabelURL("http://b.com");
        assertFalse(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchAxisLineVisible() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setAxisLineVisible(false);
        assertFalse(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchAxisLineStroke() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setAxisLineStroke(new BasicStroke(2.0f));
        assertFalse(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchAxisLinePaint() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setAxisLinePaint(Color.BLUE);
        assertFalse(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchTickLabelsVisible() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setTickLabelsVisible(false);
        assertFalse(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchTickLabelFont() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setTickLabelFont(new Font("SansSerif", Font.BOLD, 10));
        assertFalse(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchTickLabelPaint() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setTickLabelPaint(Color.GREEN);
        assertFalse(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchTickLabelInsets() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setTickLabelInsets(new org.jfree.chart.util.RectangleInsets(5, 5, 5, 5));
        assertFalse(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchTickMarksVisible() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setTickMarksVisible(false);
        assertFalse(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchTickMarkInsideLength() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setTickMarkInsideLength(5.0f);
        assertFalse(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchTickMarkOutsideLength() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setTickMarkOutsideLength(10.0f);
        assertFalse(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchTickMarkPaint() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setTickMarkPaint(Color.CYAN);
        assertFalse(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchTickMarkStroke() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setTickMarkStroke(new BasicStroke(5.0f));
        assertFalse(axis1.equals(axis2));
    }

    @Test
    public void testEquals_MismatchFixedDimension() {
        setupAxis(axis1);
        setupAxis(axis2);
        axis2.setFixedDimension(100.0);
        assertFalse(axis1.equals(axis2));
    }

    private void setupAxis(Axis axis) {
        axis.setVisible(true);
        axis.setLabel("Test Label");
        axis.setLabelFont(new Font("Arial", Font.PLAIN, 12));
        axis.setLabelPaint(Color.BLACK);
        axis.setLabelInsets(new org.jfree.chart.util.RectangleInsets(1, 1, 1, 1));
        axis.setLabelAngle(0.5);
        axis.setLabelToolTip("Tooltip");
        axis.setLabelURL("http://test.com");
        axis.setAxisLineVisible(true);
        axis.setAxisLineStroke(new BasicStroke(1.0f));
        axis.setAxisLinePaint(Color.GRAY);
        axis.setTickLabelsVisible(true);
        axis.setTickLabelFont(new Font("Arial", Font.PLAIN, 10));
        axis.setTickLabelPaint(Color.BLACK);
        axis.setTickLabelInsets(new org.jfree.chart.util.RectangleInsets(2, 2, 2, 2));
        axis.setTickMarksVisible(true);
        axis.setTickMarkInsideLength(2.0f);
        axis.setTickMarkOutsideLength(2.0f);
        axis.setTickMarkPaint(Color.BLACK);
        axis.setTickMarkStroke(new BasicStroke(1.0f));
        axis.setFixedDimension(50.0);
    }
}
